package com.gta.launcher.activity;
import org.junit.Test;import static org.junit.Assert.*;import java.io.*;import java.nio.file.*;import java.util.*;
public class ImgArchive43Test {
 private File fixture()throws Exception{File f=File.createTempFile("bcg_img_",".img");try(RandomAccessFile r=new RandomAccessFile(f,"rw")){r.writeInt(0x56455232);r.writeInt(Integer.reverseBytes(4));String[] names={"landstal.dff","rancher.dff","sadler.dff","other.dff"};for(int i=0;i<4;i++){r.writeInt(Integer.reverseBytes(i+1));r.writeByte(1);r.writeByte(0);r.writeShort(0);byte[] name=new byte[24];System.arraycopy(names[i].getBytes("US-ASCII"),0,name,0,names[i].length());r.write(name);}r.setLength(5*2048);for(int i=1;i<=4;i++){r.seek(i*2048);r.writeInt(i);}}return f;}
 @Test public void appendThreeKeepOriginalAndUnrelated()throws Exception{File original=fixture(),out=File.createTempFile("bcg_patched_",".img");byte[] before=Files.readAllBytes(original.toPath());Map<String,byte[]> models=new LinkedHashMap<>();models.put("landstal.dff",new byte[4097]);models.put("rancher.dff",new byte[6000]);models.put("sadler.dff",new byte[8200]);ImgArchive43.replace(original,out,models);assertArrayEquals(before,Files.readAllBytes(original.toPath()));try(RandomAccessFile r=new RandomAccessFile(out,"r")){for(int i=0;i<3;i++){r.seek(8+i*32);int offset=Integer.reverseBytes(r.readInt());assertTrue(offset>=5);int sectors=r.readUnsignedByte()|(r.readUnsignedByte()<<8);assertTrue(sectors>=3);r.seek(offset*2048L);assertEquals(0,r.readInt());}r.seek(8+3*32);assertEquals(4,Integer.reverseBytes(r.readInt()));r.seek(4*2048);assertEquals(4,r.readInt());}original.delete();out.delete();}
 @Test public void missingModelCannotChangeOriginal()throws Exception{File original=fixture(),out=File.createTempFile("bcg_missing_",".img");byte[] before=Files.readAllBytes(original.toPath());try{ImgArchive43.replace(original,out,Collections.singletonMap("missing.dff",new byte[16]));fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("ausente"));}assertArrayEquals(before,Files.readAllBytes(original.toPath()));original.delete();out.delete();}
 @Test public void rejectsDirectoryBeyondFile()throws Exception{File original=fixture(),out=File.createTempFile("bcg_bad_",".img");try(RandomAccessFile r=new RandomAccessFile(original,"rw")){r.seek(4);r.writeInt(Integer.reverseBytes(10000));}try{ImgArchive43.replace(original,out,Collections.emptyMap());fail();}catch(IOException expected){assertTrue(expected.getMessage().contains("inválido"));}original.delete();out.delete();}
}
